APIs used: setWindowTitle, setDistance, setTarget, enableMouseInput, createPlane, from, setBaseColor, setMetallic, setRoughness, angle, setSpot, Vec3, setDiffuse, setIntensity, setAttenuation, setLensShift, setProjectorAspect, enableShadow, allocate, setProjectionTexture, getTexture, fill, setDirectional, loadFromString, setIesProfile, loadProcedural, setEnvironment, clear, begin, clearLights, addLight, setCameraPosition, getPosition, beginShadowPass, endShadowPass, clearMaterial, setColor, drawBitmapString, rotate, getWidth, getElapsedTimef, getHeight, fmod, Color, fromHSB, drawRect, drawLine, mousePressed, MouseEventArgs, mouseReleased

