        // Save screenshot using OS window capture feature
        if (saveScreenshot(filepath)) {
            logNotice("tcApp") << "Saved: " << filepath.string();
            screenshotCount++;
        } else {
            logWarning("tcApp") << "Failed to save: " << filepath.string();
        }
    }
}

