void tcApp::keyPressed(int key) {
    if (key == KEY_ESCAPE) {
        sapp_request_quit();
    }
    else if (key == KEY_SPACE) {
        mode_ = (mode_ + 1) % NUM_MODES;
        logNotice("tcApp") << "Mode: " << mode_;
    }
}

void tcApp::mousePressed(const MouseEventArgs& e) {
    if (mode_ == 3) {
        // Spawn particles
        for (int i = 0; i < 20; i++) {
            spawnParticle(e.pos.x, e.pos.y);
        }
    }
}

