class FixedChild : public Node {
public:
    float size = 30.0f;
    float hue = 0.0f;

    void draw() override {
        // Set color based on hue
        float r = (sin(hue) * 0.5f + 0.5f);
        float g = (sin(hue + TAU / 3) * 0.5f + 0.5f);
        float b = (sin(hue + TAU * 2 / 3) * 0.5f + 0.5f);

        setColor(r, g, b);
        drawRect(-size/2, -size/2, size, size);
    }
};

