    if (key == ' ') {
        if (musicLoaded) {
            if (music.isPlaying() || music.isPaused()) {
                music.stop();
                logNotice("tcApp") << "Music stopped";
            } else {
                music.play();
                logNotice("tcApp") << "Music playing";
