// ===== tcApp.h =====
```cpp
#pragma once

#include <TrussC.h>
#include <tcxMidi.h>

#include <atomic>
#include <deque>
#include <mutex>
#include <string>

using namespace tc;
using namespace tcx;
using namespace std;

// =============================================================================
// Asynchronous input (event callback on the MIDI thread).
//
// Instead of polling in update(), we attach a listener to midiIn_.onMessage.
// The callback fires on libremidi's input thread the instant a message
// arrives - NOT on the main (update/draw) thread.
//
//   [!] Rules for the callback:
//       - guard any data shared with draw()/update() using a mutex
//       - do NOT draw or call any graphics/GL from it (main thread only)
//       - keep it short
//
// Compare with example-basic, which polls the same data on the main thread.
// =============================================================================

class tcApp : public App {
public:
    void setup() override;
    void update() override;
    void draw() override;
    void cleanup() override;

private:
    MidiIn midiIn_;
    bool   started_ = false;

    // Shared between the MIDI thread (writer) and draw() (reader).
    mutex             historyMutex_;
    deque<string>     history_;
    atomic<int>       received_{0};
    static constexpr size_t MAX_LINES = 20;

    // Keep the listener alive (it disconnects when destroyed). Declared last
    // so it is destroyed first - before midiIn_ / the shared data it touches.
    EventListener listener_;
};

```

// ===== tcApp.cpp =====
```cpp
#include "TrussC.h"
#include "tcApp.h"

void tcApp::setup() {
    // Attach the listener now; the callback runs on the MIDI input thread.
    // (Member-function style also works: onMessage.listen(this, &tcApp::onMidi).)
    listener_ = midiIn_.onMessage.listen([this](MidiMessage& m) {
        // *** MIDI thread - not the main thread. ***
        // Touch shared data only under the lock; never draw here.
        {
            lock_guard<mutex> lock(historyMutex_);
            history_.push_back(m.toString());
            while (history_.size() > MAX_LINES) history_.pop_front();
        }
        received_++;  // atomic, so the counter is fine to bump lock-free
    });
    // The port is opened in update() once midiReady() (deferred on the web).
}

void tcApp::update() {
    if (!started_ && midiReady()) {
        started_ = true;
        for (auto& d : MidiIn::listDevices())
            logNotice("midi") << "in [" << d.getPortNumber() << "] " << d.getName();
        midiIn_.openPort(0);
    }
}

void tcApp::draw() {
    clear(0.12f);
    setColor(1.0f);
    drawBitmapString("tcxMidi - async (callback on MIDI thread, mutex-guarded)", 16, 28);
    drawBitmapString("in: " + (midiIn_.isOpen() ? midiIn_.getName() : string("(none)")), 16, 52);
    drawBitmapString("received: " + to_string(received_.load()), 16, 70);

    setColor(0.55f);
    drawBitmapString("--- incoming (newest at bottom) ---", 16, 98);
    setColor(0.85f);
    {
        lock_guard<mutex> lock(historyMutex_);
        float y = 118;
        for (const auto& line : history_) {
            drawBitmapString(line, 16, y);
            y += 16;
        }
    }
}

void tcApp::cleanup() {
    // Stop the input thread before teardown so the callback can't fire late.
    listener_.disconnect();
    midiIn_.closePort();
}

