# tcxNodeInspector/serialize  (tcxNodeInspector addon example)
A usage example for the tcxNodeInspector addon.
APIs used: save, load, reflectToJson, JsonReadReflector, reflected, from, Color, fill, Node, transform, enableEvents, read, setColor, noFill, hitTest, intersectZPlane, scale, drawCircle, drawRect, drawTriangle, keyPressed, RectNode, setWindowTitle, setName, addChild, setPos, clear, setSelectedNode, logNotice, gold, drawBitmapString, start, size, getWindowHeight

// ===== tcApp.h =====
```cpp
#pragma once

// =============================================================================
// example-serialize - reflect once, get the inspector AND JSON save/load
//
// One TC_REFLECT block per type is all it takes. From that single declaration:
//   * the node inspector (F1) edits every field live, and
//   * reflectToJson / JsonReadReflector save and restore the node as JSON,
// with no per-field code on either side.
//
// SpriteNode shows all three TC_VALUE forms, an enum (TC_ENUM_LABELS), and a
// plain struct reflected from the outside (TC_REFLECT_FREE). The composite
// shows up as a collapsible group in the inspector and as a nested object in
// the JSON — the same grouping, two backends.
//
//   F1            toggle the inspector (click the sprite to select it)
//   S             snapshot the sprite to JSON (logged + kept in memory)
//   L             restore the sprite from the last snapshot
// =============================================================================

#include <TrussC.h>
#include <tcxImGui.h>
#include <tcxNodeInspector.h>
using namespace std;
using namespace tc;
using namespace tcx;

// An enum with human-readable labels (combo box in the inspector, label string
// in the JSON).
enum class Shape { Circle, Square, Triangle };
TC_ENUM_LABELS(Shape, "Circle", "Square", "Triangle")

// A plain value type, reflected from the outside with TC_REFLECT_FREE. Used as
// a field below, it nests into its own collapsible group / JSON object.
struct Style {
    Color fill   = colors::cornflowerBlue;
    Color stroke = colors::white;
    float strokeWidth = 2.0f;
};
TC_REFLECT_FREE(Style) {
    TC_VALUE(fill)
    TC_VALUE(stroke)
    TC_VALUE(strokeWidth)
}

// A node that reflects its own members on top of Node's transform.
class SpriteNode : public Node {
public:
    Shape shape = Shape::Circle;   // 1-arg enum
    Style style;                   // nested TC_REFLECT_FREE composite

    SpriteNode() { enableEvents(); }   // make it clickable on the canvas

    float getRadius() const { return radius_; }
    void  setRadius(float r) { radius_ = max(4.0f, r); }   // setter clamps
    float diameter() const { return radius_ * 2.0f; }      // computed, read-only

    void draw() override {
        const float r = radius_;
        setColor(style.fill);   fill();   drawShape(r);
        setColor(style.stroke); noFill(); drawShape(r);
    }

    bool hitTest(const Ray& localRay, float& outDistance) override {
        const Ray::Hit h = localRay.intersectZPlane();
        if (!h.hit) return false;
        if (h.point.x * h.point.x + h.point.y * h.point.y <= radius_ * radius_) { outDistance = h.t; return true; }
        return false;
    }

    TC_REFLECT(SpriteNode, Node) {              // pos / rotation / scale come from Node
        TC_VALUE(shape)                         // enum     -> combo / label
        TC_VALUE(radius, getRadius, setRadius)  // 3-arg    -> setter clamps
        TC_VALUE(diameter, diameter)            // 2-arg    -> read-only (greyed)
        TC_VALUE(style)                         // composite-> collapsible group
    }

private:
    float radius_ = 80.0f;

    void drawShape(float r) {
        switch (shape) {
            case Shape::Circle:   drawCircle(0, 0, r); break;
            case Shape::Square:   drawRect(-r, -r, r * 2, r * 2); break;
            case Shape::Triangle: drawTriangle(0, -r, r, r, -r, r); break;
        }
    }
};

class tcApp : public App {
public:
    void setup() override;
    void update() override;
    void draw() override;
    void keyPressed(int key) override;

private:
    shared_ptr<RectNode>   sceneRoot_;
    shared_ptr<SpriteNode> sprite_;
    Json   snapshot_;          // last saved state (S), restored by L
    string status_ = "press S to snapshot, L to restore, F1 for inspector";
};

```

// ===== tcApp.cpp =====
```cpp
#include "tcApp.h"

void tcApp::setup() {
    setWindowTitle("reflect -> inspector + JSON");

    // MCP input tools, so an AI agent can drive the demo (no-op without TRUSSC_MCP).
    mcp::registerControlTools();

    // A scene container, with one sprite to inspect / serialize.
    sceneRoot_ = make_shared<RectNode>();
    sceneRoot_->setName("scene");
    addChild(sceneRoot_);

    sprite_ = make_shared<SpriteNode>();
    sprite_->setName("sprite");
    sprite_->setPos(590, 500);   // clear of the inspector + JSON panels
    sceneRoot_->addChild(sprite_);

    // The inspector runs itself; F1 toggles it. Select the sprite to edit it.
    NodeInspector::attach(*sceneRoot_, KEY_F1).setAccent(Color(0.16f, 0.55f, 0.62f));
    setSelectedNode(sprite_.get());
}

void tcApp::update() {}

void tcApp::keyPressed(int key) {
    if (key == 'S' || key == 's') {
        // Save: one call turns the whole node (Node transform + our fields +
        // the nested Style group) into JSON.
        snapshot_ = reflectToJson(*sprite_);
        logNotice("snapshot saved:\n" + snapshot_.dump(2));
        status_ = "snapshot saved (edit in the inspector, then press L to restore)";
    } else if (key == 'L' || key == 'l') {
        if (snapshot_.is_object()) {
            // Load: apply the saved JSON back through the reflected setters.
            JsonReadReflector r(snapshot_);
            sprite_->reflectMembers(r);
            status_ = "restored from snapshot";
        } else {
            status_ = "no snapshot yet — press S first";
        }
    }
}

void tcApp::draw() {
    clear(0.11f, 0.12f, 0.13f);

    // The live JSON of the sprite, rebuilt every frame: drag a slider in the
    // inspector and watch it change here. This is the exact data S would save.
    const string json = reflectToJson(*sprite_).dump(2);
    const float x = 700;
    setColor(colors::gold);
    drawBitmapString("reflectToJson(sprite) — live:", x, 28);
    setColor(colors::lightGray);
    float y = 48;
    size_t start = 0;
    while (start <= json.size()) {
        size_t nl = json.find('\n', start);
        string line = json.substr(start, nl == string::npos ? string::npos : nl - start);
        drawBitmapString(line, x, y);
        y += 13;
        if (nl == string::npos) break;
        start = nl + 1;
    }

    setColor(0.6f, 0.6f, 0.65f);
    drawBitmapString("click the sprite to select / F1 inspector / S snapshot / L restore", 16, getWindowHeight() - 40);
    setColor(colors::white);
    drawBitmapString(status_, 16, getWindowHeight() - 22);
}

