# tcxTls/tls  (tcxTls addon example)
A usage example for the tcxTls addon.
APIs used: keyPressed, cleanup, Event, EventListener, isConnected, connect, logNotice, send, disconnect, clear, listen, TcpConnectEventArgs, success, TcpReceiveEventArgs, begin, length, TcpDisconnectEventArgs, TcpErrorEventArgs, getWindowWidth, getWindowHeight, setColor, drawBitmapString, drawLine, drawRect, close, size

// ===== tcApp.h =====
```cpp
#pragma once

#include <TrussC.h>
#include "tcTlsClient.h"
using namespace tc;

class tcApp : public App {
public:
    void setup() override;
    void update() override;
    void draw() override;
    void keyPressed(int key) override;
    void cleanup() override;

private:
    TlsClient client;

    // Event listeners
    EventListener connectListener;
    EventListener receiveListener;
    EventListener disconnectListener;
    EventListener errorListener;

    // Send log (left side)
    std::vector<std::string> sentMessages;
    std::mutex sentMutex;

    // Receive log (right side)
    std::vector<std::string> receivedMessages;
    std::mutex receivedMutex;

    // State
    bool isConnected = false;
    std::string statusMessage = "Press C to connect to httpbin.org";

    void addSent(const std::string& msg);
    void addReceived(const std::string& msg);
    void sendHttpRequest();
};

```

// ===== tcApp.cpp =====
```cpp
// =============================================================================
// tcApp.cpp - TLS (HTTPS) Client Sample
// =============================================================================

#include "tcApp.h"
#include <sstream>

using namespace std;

void tcApp::setup() {
    logNotice() << "=== TLS (HTTPS) Client Example ===";
    logNotice() << "Press C to connect to httpbin.org (HTTPS)";
    logNotice() << "Press SPACE to send HTTP GET request";
    logNotice() << "Press D to disconnect";
    logNotice() << "Press X to clear log";
    logNotice() << "==================================";

    // TLS configuration (no certificate verification - for testing)
    client.setVerifyNone();

    // Connect event
    connectListener = client.onConnect.listen([this](TcpConnectEventArgs& e) {
        if (e.success) {
            isConnected = true;
            statusMessage = "Connected! TLS: " + client.getTlsVersion() + " / " + client.getCipherSuite();
            addReceived("--- Connected ---");
            addReceived("TLS Version: " + client.getTlsVersion());
            addReceived("Cipher: " + client.getCipherSuite());
        } else {
            statusMessage = "Connection failed: " + e.message;
            addReceived("--- Connection failed ---");
        }
    });

    // Receive event
    receiveListener = client.onReceive.listen([this](TcpReceiveEventArgs& e) {
        string data(e.data.begin(), e.data.end());

        // Split if too long
        istringstream iss(data);
        string line;
        while (getline(iss, line)) {
            if (line.length() > 80) {
                line = line.substr(0, 77) + "...";
            }
            addReceived(line);
        }
    });

    // Disconnect event
    disconnectListener = client.onDisconnect.listen([this](TcpDisconnectEventArgs& e) {
        isConnected = false;
        statusMessage = "Disconnected: " + e.reason;
        addReceived("--- Disconnected ---");
    });

    // Error event
    errorListener = client.onError.listen([this](TcpErrorEventArgs& e) {
        addReceived("ERROR: " + e.message);
    });
}

void tcApp::update() {
}

void tcApp::draw() {
    clear(0.12f);

    float w = getWindowWidth();
    float h = getWindowHeight();
    float midX = w / 2;

    // Title
    setColor(1.0f);
    drawBitmapString("TLS (HTTPS) Client Example", 40, 30);

    // Status display
    if (isConnected) {
        setColor(0.4f, 1.0f, 0.4f);
    } else {
        setColor(1.0f, 0.4f, 0.4f);
    }
    drawBitmapString(statusMessage, 40, 55);

    // Instructions
    setColor(0.7f);
    drawBitmapString("C: Connect  SPACE: Send Request  D: Disconnect  X: Clear", 40, 80);

    // Center divider line
    setColor(0.3f);
    drawLine(midX, 100, midX, h - 20);

    // Left side: Send log
    setColor(0.4f, 0.8f, 1.0f);
    drawBitmapString("SENT", 40, 110);
    setColor(0.24f);
    drawRect(30, 125, midX - 50, h - 150);

    setColor(0.8f, 0.86f, 1.0f);
    float y = 140;
    {
        lock_guard<mutex> lock(sentMutex);
        for (const auto& msg : sentMessages) {
            drawBitmapString(msg, 40, y);
            y += 16;
            if (y > h - 40) break;
        }
    }

    // Right side: Receive log
    setColor(0.4f, 1.0f, 0.4f);
    drawBitmapString("RECEIVED", midX + 20, 110);
    setColor(0.24f);
    drawRect(midX + 10, 125, midX - 50, h - 150);

    setColor(0.8f, 1.0f, 0.8f);
    y = 140;
    {
        lock_guard<mutex> lock(receivedMutex);
        for (const auto& msg : receivedMessages) {
            drawBitmapString(msg, midX + 20, y);
            y += 16;
            if (y > h - 40) break;
        }
    }
}

void tcApp::keyPressed(int key) {
    if (key == 'C' || key == 'c') {
        if (!isConnected) {
            statusMessage = "Connecting to httpbin.org:443...";
            addSent("Connecting to httpbin.org:443...");

            // HTTPS connection
            if (client.connect("httpbin.org", 443)) {
                // Connection success is notified via onConnect
            }
        } else {
            statusMessage = "Already connected";
        }
    } else if (key == KEY_SPACE || key == ' ') {
        if (isConnected) {
            sendHttpRequest();
        } else {
            statusMessage = "Not connected. Press C first.";
        }
    } else if (key == 'D' || key == 'd') {
        if (isConnected) {
            client.disconnect();
        }
    } else if (key == 'X' || key == 'x') {
        {
            lock_guard<mutex> lock(sentMutex);
            sentMessages.clear();
        }
        {
            lock_guard<mutex> lock(receivedMutex);
            receivedMessages.clear();
        }
        statusMessage = "Log cleared";
    }
}

void tcApp::sendHttpRequest() {
    // Send HTTP GET request
    string request =
        "GET /get HTTP/1.1\r\n"
        "Host: httpbin.org\r\n"
        "User-Agent: TrussC/1.0\r\n"
        "Accept: */*\r\n"
        "Connection: close\r\n"
        "\r\n";

    addSent("--- HTTP Request ---");
    addSent("GET /get HTTP/1.1");
    addSent("Host: httpbin.org");
    addSent("User-Agent: TrussC/1.0");
    addSent("Accept: */*");
    addSent("Connection: close");

    if (client.send(request)) {
        addSent("--- Sent successfully ---");
    } else {
        addSent("--- Send failed ---");
    }
}

void tcApp::cleanup() {
    client.disconnect();
}

void tcApp::addSent(const string& msg) {
    logNotice() << "[SENT] " << msg;
    lock_guard<mutex> lock(sentMutex);
    sentMessages.push_back(msg);
    if (sentMessages.size() > 30) {
        sentMessages.erase(sentMessages.begin());
    }
}

void tcApp::addReceived(const string& msg) {
    logNotice() << "[RECV] " << msg;
    lock_guard<mutex> lock(receivedMutex);
    receivedMessages.push_back(msg);
    if (receivedMessages.size() > 30) {
        receivedMessages.erase(receivedMessages.begin());
    }
}

```

