// ===== tcApp.h =====
```cpp
#pragma once

#include <TrussC.h>
#include <tcxDepthCamera.h>
#include <tcxAzureKinect.h>
#include <tcxAzureKinectBodyTracking.h>
using namespace std;
using namespace tc;
using namespace tcx;

// Point cloud + k4abt skeleton overlay, driven by one Azure Kinect / Femto Bolt.
// The camera grabs each frame; the body tracker reuses that same capture (via
// AzureKinect::getNativeCapture()) so one device feeds both. Requires the hardware
// + the Azure Kinect Body Tracking SDK runtime (see README). Runs and shows a
// message if no device / tracker is available, rather than crashing.
class tcApp : public App {
public:
    void setup() override;
    void update() override;
    void draw() override;
    void keyPressed(int key) override;

private:
    void rebuild();
    void drawSkeletons();

    void applyMode();   // (re)create the tracker with the current mode

    shared_ptr<AzureKinect> camera;
    BodyTracker             tracker;
    bool deviceOk  = false;
    bool trackerOk = false;

    // Inference backend, cycled live with 'M'. Default CPU: on a weak GPU (e.g.
    // Quadro P1000) DirectML can be slower; on a strong NVIDIA box switch to
    // CUDA / TENSORRT (those need the CUDA/cuDNN runtime installed).
    BodyTracker::Mode mode = BodyTracker::Mode::Cpu;

    EasyCam view;
    Mesh    cloud;
    bool    colored = true;
    int     step    = 2;

    // World coords (meters, +Y down) -> viewer units (scaled, +Y up). Same factor
    // for the cloud and the skeleton so they stay aligned.
    static constexpr float kViewScale = 100.0f;
};

```

// ===== tcApp.cpp =====
```cpp
#include "tcApp.h"

void tcApp::setup() {
    setWindowTitle("tcxAzureKinectBodyTracking - skeletons");

    camera = make_shared<AzureKinect>();
    // Body tracking shares the per-frame k4a_capture via getNativeCapture(), which
    // is only safe on the thread driving update() — so run the camera NON-threaded.
    camera->setThreaded(false);
    camera->enableDepth();
    camera->enableColor();
    camera->enableInfrared();
    deviceOk = camera->setup();
    if (!deviceOk) {
        logError("example-basic") << "Azure Kinect / Femto not available — device "
                                     "connected and the k4a (or Orbbec Wrapper) runtime installed?";
    } else {
        applyMode();
    }

    view.setTarget(0.0f, 0.0f, 0.0f);
    view.setDistance(500.0f);
    view.setElevation(-20.0f);   // tilt off the true side view so the scene reads
    view.enableMouseInput();
}

static const char* modeName(BodyTracker::Mode m) {
    switch (m) {
        case BodyTracker::Mode::Auto:     return "Auto";
        case BodyTracker::Mode::Cpu:      return "CPU";
        case BodyTracker::Mode::Cuda:     return "CUDA";
        case BodyTracker::Mode::DirectML: return "DirectML";
        case BodyTracker::Mode::TensorRT: return "TensorRT";
    }
    return "?";
}

// (Re)create the k4abt tracker with the current `mode`. Safe to call live — closes
// the old tracker first. trackerOk reflects whether the mode is usable here (e.g.
// CUDA fails without the CUDA/cuDNN runtime).
void tcApp::applyMode() {
    if (!deviceOk) return;
    trackerOk = tracker.setup(*camera, mode);
    if (!trackerOk) {
        logError("example-basic") << "k4abt tracker failed to start in " << modeName(mode)
                                  << " mode — runtime missing? (DNN model + onnxruntime/"
                                     "directml or CUDA/cuDNN DLLs next to the exe)";
    } else {
        logNotice("example-basic") << "body tracker running in " << modeName(mode) << " mode";
    }
}

void tcApp::update() {
    if (!deviceOk) return;
    camera->update();
    if (camera->isFrameNew()) {
        rebuild();
        if (trackerOk) tracker.update(*camera);   // reuses this frame's capture
    }
}

void tcApp::rebuild() {
    cloud = camera->toMesh({.colors = colored, .step = step});
    // meters,+Y down -> viewer units,+Y up. Camera stays at the origin (orbit pivot).
    cloud.scale(kViewScale, -kViewScale, kViewScale);
}

// Draw each tracked body as bones (lines) + joints (small spheres), in the same
// scaled/flipped space as the point cloud.
void tcApp::drawSkeletons() {
    if (!trackerOk) return;
    const Vec3 s(kViewScale, -kViewScale, kViewScale);

    for (const Body& b : tracker.bodies()) {
        setColor(1.0f, 0.85f, 0.2f);
        for (const auto& bone : boneList()) {
            const BodyJoint& a = b.joint(bone.first);
            const BodyJoint& c = b.joint(bone.second);
            if (a.confidence == JointConfidence::None ||
                c.confidence == JointConfidence::None) continue;
            drawLine(Vec3(a.position.x * s.x, a.position.y * s.y, a.position.z * s.z),
                     Vec3(c.position.x * s.x, c.position.y * s.y, c.position.z * s.z));
        }
        setColor(1.0f, 0.3f, 0.3f);
        for (const BodyJoint& j : b.joints) {
            if (j.confidence == JointConfidence::None) continue;
            drawSphere(Vec3(j.position.x * s.x, j.position.y * s.y, j.position.z * s.z), 1.5f);
        }
    }
    setColor(1.0f);
}

void tcApp::draw() {
    clear(0.08f, 0.09f, 0.11f);

    if (deviceOk) {
        view.begin();
        pushMatrix();
        if (!colored) setColor(0.55f, 0.75f, 1.0f);
        cloud.draw();
        drawSkeletons();
        popMatrix();
        view.end();
    }

    setColor(1.0f);
    string hud;
    if (deviceOk) {
        hud  = "tcxAzureKinectBodyTracking\n";
        hud += to_string(cloud.getNumVertices()) + " points";
        hud += colored ? "  [colored]" : "  [plain]";
        hud += "\nmode: " + string(modeName(mode));
        hud += trackerOk ? ("   bodies: " + to_string(tracker.numBodies()))
                         : "   (tracker NOT running — see log)";
        hud += "\nC: color   M: inference mode   1-4: decimation   drag: orbit";
    } else {
        hud  = "No Azure Kinect / Femto device found.\n";
        hud += "Connect the camera, install the k4a (or Orbbec Wrapper) +\n";
        hud += "Body Tracking SDK runtime, and relaunch.";
    }
    drawBitmapString(hud, 20, 20);
}

void tcApp::keyPressed(int key) {
    if (key == 'c' || key == 'C') {
        colored = !colored;
    } else if (key == 'm' || key == 'M') {
        // Cycle the inference backend and rebuild the tracker live.
        static const BodyTracker::Mode cycle[] = {
            BodyTracker::Mode::Cpu, BodyTracker::Mode::DirectML,
            BodyTracker::Mode::Cuda, BodyTracker::Mode::TensorRT };
        int i = 0;
        for (; i < 4; ++i) if (cycle[i] == mode) break;
        mode = cycle[(i + 1) % 4];
        applyMode();
    } else if (key >= '1' && key <= '4') {
        step = key - '0';
    }
    if (deviceOk) rebuild();
}

